def _deep_require_pos_int(value, name):
    """正 int 契约（拒绝 bool）：类型错抛 TypeError，非正抛 ValueError。"""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            "%s 必须是 int（拒绝 bool），得到 %s"
            % (name, type(value).__name__)
        )
    if value <= 0:
        raise ValueError("%s 必须为正整数" % name)


def _deep_require_seed(seed):
    """洗牌 LCG 种子契约：[0, 2^32-1] 内 int（拒绝 bool）。"""
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise TypeError(
            "seed 必须是 int（拒绝 bool），得到 %s" % type(seed).__name__
        )
    if seed < 0 or seed > 0xFFFFFFFF:
        raise ValueError("seed 必须满足 0 <= seed <= 2^32-1")


def _deep_require_shuffle(shuffle):
    """shuffle 必须为 bool，否则抛 TypeError。"""
