        raise ValueError("momentum 必须满足 0 <= momentum < 1")


def _deep_check_adam_beta(value, name):
    """Adam 衰减系数契约：[0,1) 内的有限 int/float（拒绝 bool）。

    类型错（含 bool 或非 int/float）抛 TypeError，非有限或越界抛
    ValueError。
    """
