                raise ValueError(
                    "%s 的 %s[%d] 含有非有限值（NaN/inf）"
                    % (what, group_name, i)
                )


# 八组参数的组序与显示名：conv 权重/偏置、归一化层（实际为 BatchNorm2D
# 或 GroupNorm2D）gamma/beta、第一个 Linear 权重/偏置、第二个 Linear
