    # 与对应参数同形、叶值有限。校验阶段即复制，绝不修改入参 velocity。
    if velocity is None:
        vel = [
            _deep_zeros_like(getattr(owner, attr))
            for owner, attr in param_attrs
        ]
    else:
        if not isinstance(velocity, tuple):
            raise TypeError(
                "velocity 必须是 None 或 8 项 tuple，得到 %s"
                % type(velocity).__name__
            )
        if len(velocity) != 8:
            raise ValueError(
                "velocity 必须恰含 8 项，得到 %d 项" % len(velocity)
            )
        vel = []
        for v_tree, (owner, attr), vname in zip(
            velocity, param_attrs, _DEEP_GROUP_NAMES
        ):
            _deep_check_state_tree(v_tree, getattr(owner, attr), vname,
                                   "velocity")
            vel.append(_deep_copy(v_tree))

    (
        cur_epoch, cur_order, cur_cursor, cur_s,
        cur_pending_samples, cur_pending_micro,
        cur_pending_loss, cur_pending_grads,
    ) = _deep_parse_accum_state(
        state, epochs, n_, seed, microbatch_size, accum_steps, layers
    )
    if (
        cur_epoch == epochs
        and (
            (max_updates is not None and max_updates > 0)
            or (max_microbatches is not None and max_microbatches > 0)
        )
    ):
        raise ValueError("训练已完成（epoch == epochs），不得继续训练")

    snapshot = _snapshot_deep_layers(layers)
    try:
        losses = []
        grad_norms = []
        epoch_idx = cur_epoch
        order = list(cur_order)
        start = cur_cursor
        s = cur_s
        remaining_updates = max_updates
        remaining_micro = max_microbatches
        done = max_updates == 0 or max_microbatches == 0
        acc_count = cur_pending_samples
        acc_micro = cur_pending_micro
        acc_loss = cur_pending_loss
        acc_grads = (
            [_deep_copy(g) for g in cur_pending_grads]
            if cur_pending_grads is not None else None
        )

        while not done and epoch_idx < epochs:
            if not order:
                if remaining_updates == 0 or remaining_micro == 0:
                    done = True
                    continue
                start = 0
                order = list(range(n_))
                s = _deep_shuffle_order(order, n_, s, shuffle)
            while start < n_:
                idx = order[start:start + microbatch_size]
                batch_x = [x[k] for k in idx]
                batch_labels = [labels[k] for k in idx]

                loss_value, micro_groups = _deep_forward_backward(
                    layers, batch_x, batch_labels
                )

                msize = len(idx)
                acc_loss = acc_loss + loss_value * msize
                if not math.isfinite(acc_loss):
                    raise ValueError("训练计算产生非有限值（NaN/inf）")
                if acc_grads is None:
                    acc_grads = [
                        _deep_zeros_like(g) for g in micro_groups
                    ]
                acc_grads = [
                    _deep_tree_add_scaled(a, g, msize)
                    for a, g in zip(acc_grads, micro_groups)
                ]
                acc_count += msize
                acc_micro += 1
                start += msize

                if remaining_micro is not None:
                    remaining_micro -= 1

                settled = acc_micro >= accum_steps or start >= n_
                if not settled:
                    if remaining_micro == 0:
                        done = True
                        break
                    continue

                mean_loss = acc_loss / acc_count
                if not math.isfinite(mean_loss):
                    raise ValueError("训练计算产生非有限值（NaN/inf）")
                grad_groups = tuple(
                    _deep_tree_div(a, acc_count) for a in acc_grads
                )
                grad_norm = _deep_global_grad_norm(grad_groups)
                grad_groups = _deep_clip_grad_groups(
                    grad_groups, clip, grad_norm
                )
                # 先裁剪梯度，再逐叶 v=momentum*v+g、p=p-lr*v；仅结算时
                # 推进速度，未结算微批不影响 v。
                vel = _deep_momentum_commit(
                    param_attrs, vel, grad_groups, momentum, lr
                )

                losses.append(float(mean_loss))
                grad_norms.append(grad_norm)

                acc_count = 0
                acc_loss = 0.0
                acc_grads = None
                acc_micro = 0

                if remaining_updates is not None:
                    remaining_updates -= 1
                if start >= n_:
                    epoch_idx += 1
                    order = []
                    start = 0
                    break
                if remaining_updates == 0 or remaining_micro == 0:
                    done = True
                    break
        out_velocity = tuple(vel)
        out_state = _deep_build_accum_out_state(
            epoch_idx, order, start, s,
            acc_count, acc_micro, acc_loss, acc_grads,
        )
        return losses, grad_norms, out_velocity, out_state
    except BaseException:
        _restore_deep_layers(layers, snapshot)
