def _deep_check_state_tree(value, ref, group_name, what):
    """校验 velocity/m/v/pending_grads 的单组嵌套 list。

    与对应参数同形，叶为有限 int/float（拒绝 bool）。what 为出错消息中
    的字段名（"velocity" 或 "state 的 pending_grads"）。容器或叶类型错
    抛 TypeError，长度/形状不符、层级错位或叶非有限抛 ValueError。
    """
    if not isinstance(value, list):
        raise TypeError(
            "%s 的 %s 必须是嵌套 list，得到 %s"
            % (what, group_name, type(value).__name__)
        )
    if len(value) != len(ref):
        raise ValueError(
            "%s 的 %s 长度 %d 与参数形状 %d 不符"
            % (what, group_name, len(value), len(ref))
        )
    for i, (v_child, p_child) in enumerate(zip(value, ref)):
        if isinstance(p_child, list):
            if not isinstance(v_child, list):
                raise TypeError(
                    "%s 的 %s[%d] 必须是 list，得到 %s"
                    % (what, group_name, i, type(v_child).__name__)
                )
            _deep_check_state_tree(
                v_child, p_child, "%s[%d]" % (group_name, i), what
            )
        else:
            if isinstance(v_child, list):
                raise ValueError(
                    "%s 的 %s[%d] 层级过深：标量位置出现了 list"
                    % (what, group_name, i)
                )
            if isinstance(v_child, bool) or not isinstance(
                v_child, (int, float)
            ):
                raise TypeError(
                    "%s 的 %s[%d] 元素必须是 int/float（拒绝 bool）"
                    "，得到 %s"
                    % (what, group_name, i, type(v_child).__name__)
                )
            if not math.isfinite(v_child):
                raise ValueError(
                    "%s 的 %s[%d] 含有非有限值（NaN/inf）"
                    % (what, group_name, i)
                )


